import{describe,expect,it}from'vitest';
import{currentOfficialSourceAttemptSignal,fetchWithOfficialTimeout,runWithOfficialSourceAttemptTimeout,runWithOfficialSourceCancellation}from'../../src/crawler/officialHttpRuntimeLimits';
describe('portable ownership cancellation',()=>{
 it('does not execute after ownership was already lost',async()=>{const c=new AbortController();c.abort(Error('lost'));let called=false;await expect(runWithOfficialSourceCancellation(c.signal,async()=>{called=true;})).rejects.toThrow('lost');expect(called).toBe(false);});
 it('propagates lease loss into an in-flight normal HTTP request',async()=>{const c=new AbortController();const p=runWithOfficialSourceAttemptTimeout(()=>runWithOfficialSourceCancellation(c.signal,()=>fetchWithOfficialTimeout('https://example.test/',{}, {fetchImpl:async(_url,init)=>new Promise((_resolve,reject)=>{init!.signal!.addEventListener('abort',()=>reject(init!.signal!.reason),{once:true});})})),1000);c.abort(Error('lease lost'));await expect(p).rejects.toThrow('lease lost');expect(currentOfficialSourceAttemptSignal()).toBeUndefined();});
 it('preserves the source timeout even when the ownership lease remains live',async()=>{const c=new AbortController();await expect(runWithOfficialSourceAttemptTimeout(()=>runWithOfficialSourceCancellation(c.signal,()=>new Promise(()=>{})),5)).rejects.toThrow(/source attempt exceeded/i);expect(c.signal.aborted).toBe(false);expect(currentOfficialSourceAttemptSignal()).toBeUndefined();});
 it('cleans up cancellation context on success',async()=>{const c=new AbortController();expect(await runWithOfficialSourceCancellation(c.signal,async()=>{expect(currentOfficialSourceAttemptSignal()).toBeDefined();return 1;})).toBe(1);expect(currentOfficialSourceAttemptSignal()).toBeUndefined();});
});
